/**
 * WWHD Online P2P Signaling Worker
 *
 * Cloudflare Worker that maps 6-char room codes to { ip, port, secret }.
 * The session secret is a 64-char hex string (32 raw bytes) generated by the
 * host and stored here.  Joiners receive it in the GET response so they can
 * authenticate to the host's ENet server via MSG_AUTH_REQ.  This prevents
 * connecting to a room without first going through the signaling server.
 *
 * API:
 *   POST   /rooms          body: { code, ip, port, secret }
 *   GET    /rooms/:code    → 200 { ip, port, secret } | 404
 *   DELETE /rooms/:code    → 204
 *
 * KV namespace binding: ROOMS  (set up in wrangler.toml)
 * Room TTL: 2 hours.
 */

const ROOM_TTL_SECONDS = 7200;
const CODE_RE   = /^[23456789A-HJ-NP-Z]{6}$/;
const SECRET_RE = /^[0-9a-f]{64}$/;        /* 32 bytes as lowercase hex */

export default {
  async fetch(request, env) {
    const url  = new URL(request.url);
    const path = url.pathname;

    /* ── CORS pre-flight ── */
    if (request.method === 'OPTIONS') {
      return new Response(null, { status: 204, headers: cors_headers() });
    }

    /* ── POST /rooms ── register a new room ── */
    if (request.method === 'POST' && path === '/rooms') {
      let body;
      try { body = await request.json(); } catch {
        return err(400, 'invalid JSON');
      }
      const { code, ip, port, secret } = body ?? {};
      if (!code   || !CODE_RE.test(code))          return err(400, 'invalid code');
      if (!ip     || typeof ip !== 'string')        return err(400, 'missing ip');
      if (!port   || typeof port !== 'number')      return err(400, 'missing port');
      if (!secret || !SECRET_RE.test(secret))       return err(400, 'missing or invalid secret');

      /* Reject if a room with this code already exists (prevent code squatting). */
      const existing = await env.ROOMS.get(code);
      if (existing) return err(409, 'code already in use');

      await env.ROOMS.put(code, JSON.stringify({ ip, port, secret }),
                          { expirationTtl: ROOM_TTL_SECONDS });
      return json({ ok: true, code }, 201);
    }

    /* ── GET /rooms/:code ── look up a room ── */
    const get_match = path.match(/^\/rooms\/([^/]+)$/);
    if (request.method === 'GET' && get_match) {
      const code = get_match[1].toUpperCase();
      if (!CODE_RE.test(code)) return err(400, 'invalid code');

      const val = await env.ROOMS.get(code);
      if (!val) return err(404, 'room not found');

      /* Return ip, port AND secret so the joiner can authenticate. */
      return json(JSON.parse(val), 200);
    }

    /* ── DELETE /rooms/:code ── remove a room ── */
    const del_match = path.match(/^\/rooms\/([^/]+)$/);
    if (request.method === 'DELETE' && del_match) {
      const code = del_match[1].toUpperCase();
      if (!CODE_RE.test(code)) return err(400, 'invalid code');

      await env.ROOMS.delete(code);
      return new Response(null, { status: 204, headers: cors_headers() });
    }

    return err(404, 'not found');
  }
};

/* ── helpers ── */

function cors_headers() {
  return {
    'Access-Control-Allow-Origin':  '*',
    'Access-Control-Allow-Methods': 'GET, POST, DELETE, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type',
  };
}

function json(obj, status = 200) {
  return new Response(JSON.stringify(obj), {
    status,
    headers: { 'Content-Type': 'application/json', ...cors_headers() },
  });
}

function err(status, message) {
  return json({ error: message }, status);
}
